from __future__ import annotations

"""Idempotency key selection for at-least-once Lambda `OrderPlaced` handlers."""

from receipt_models import OrderPlacedEvent

AUDIT_ACTION_RECEIPT_SENT = "receipt_sent"
AUDIT_ACTION_DUPLICATE_RETRY = "duplicate_retry"


def starter_dedupe_lookup_token(event: OrderPlacedEvent) -> str:
    """Starter bug: keys off Lambda request id so each retry looks like a new order."""
    return event.lambda_request_id.strip()


def production_dedupe_lookup_token(event: OrderPlacedEvent) -> str:
    """Stable business key: one visible receipt per `order_id`."""
    return event.order_id.strip()


def idempotency_boundary_label(kind: str) -> str:
    return f"idempotency::{kind}"


def invocation_correlation_label(event: OrderPlacedEvent) -> str:
    return f"{event.lambda_request_id}:{event.retry_attempt}"


def request_id_is_retry(event: OrderPlacedEvent) -> bool:
    return event.retry_attempt > 0


def merge_audit_reasons(primary: str, secondary: str | None) -> str:
    if secondary:
        return f"{primary}|{secondary}"
    return primary


def receipt_sequence_suffix(ordinal: int) -> str:
    if ordinal <= 0:
        raise ValueError("ordinal must be positive")
    return str(ordinal)


def format_rcpt_id(order_id: str, ordinal: int) -> str:
    return f"rcpt-{order_id}-{receipt_sequence_suffix(ordinal)}"


def dollar_amount_hint_cents(amount_cents: int) -> str:
    dollars = amount_cents // 100
    cents = amount_cents % 100
    return f"{dollars}.{cents:02d}"


def workflow_summary_keys() -> tuple[str, ...]:
    return (
        "stored_receipts",
        "sent_receipts",
        "audit_events",
        "duplicate_retries",
        "order_ids",
    )


def is_supported_audit_action(action: str) -> bool:
    return action in {AUDIT_ACTION_RECEIPT_SENT, AUDIT_ACTION_DUPLICATE_RETRY}


def explain_duplicate_detection(order_id: str, request_id: str) -> str:
    return f"duplicate_check order={order_id} req={request_id}"


def safe_preview_email(email: str) -> str:
    local, _, domain = email.partition("@")
    if not domain:
        return "***"
    return f"{local[:2]}***@{domain}"


def handler_result_statuses() -> tuple[str, ...]:
    return ("sent", "duplicate")


def handler_noise_hints() -> list[str]:
    return ["async_retry", "client_replay", "visibility_timeout"]

