from __future__ import annotations

"""In-memory Lambda receipt workflow for duplicated asynchronous invocations."""

from idempotency import (
    AUDIT_ACTION_DUPLICATE_RETRY,
    AUDIT_ACTION_RECEIPT_SENT,
    handler_result_statuses,
    starter_dedupe_lookup_token,
)
from receipt_models import OrderPlacedEvent, ReceiptRecord, normalize_currency


class InMemoryReceiptStore:
    def __init__(self) -> None:
        self._records_by_order_id: dict[str, ReceiptRecord] = {}

    def get_by_order_id(self, order_id: str) -> ReceiptRecord | None:
        return self._records_by_order_id.get(order_id)

    def save_new(self, event: OrderPlacedEvent, receipt_id: str) -> ReceiptRecord:
        record = ReceiptRecord(
            order_id=event.order_id,
            receipt_id=receipt_id,
            customer_email=event.customer_email,
            amount_cents=event.amount_cents,
            currency=normalize_currency(event.currency),
            first_lambda_request_id=event.lambda_request_id,
        )
        self._records_by_order_id[event.order_id] = record
        return record

    def all_records(self) -> list[ReceiptRecord]:
        return list(self._records_by_order_id.values())

    def record_count(self) -> int:
        return len(self._records_by_order_id)


class ReceiptSender:
    def __init__(self) -> None:
        self.sent_receipts: list[dict[str, object]] = []

    def send_receipt(self, event: OrderPlacedEvent) -> str:
        receipt_id = f"rcpt-{event.order_id}-{len(self.sent_receipts) + 1}"
        self.sent_receipts.append(
            {
                "receipt_id": receipt_id,
                "order_id": event.order_id,
                "customer_email": event.customer_email,
                "amount_cents": event.amount_cents,
                "currency": normalize_currency(event.currency),
            }
        )
        return receipt_id


class ReceiptAuditLog:
    def __init__(self) -> None:
        self.events: list[dict[str, object]] = []

    def record(self, action: str, event: OrderPlacedEvent, receipt_id: str) -> None:
        self.events.append(
            {
                "action": action,
                "order_id": event.order_id,
                "lambda_request_id": event.lambda_request_id,
                "retry_attempt": event.retry_attempt,
                "receipt_id": receipt_id,
            }
        )


def _result(record: ReceiptRecord, status: str, notification_sent: bool) -> dict[str, object]:
    allowed = handler_result_statuses()
    if status not in allowed:
        raise ValueError(f"status must be one of {allowed}")
    return {
        "status": status,
        "order_id": record.order_id,
        "receipt_id": record.receipt_id,
        "customer_email": record.customer_email,
        "amount_cents": record.amount_cents,
        "currency": record.currency,
        "notification_sent": notification_sent,
        "duplicate": status == "duplicate",
    }


def handle_order_receipt_event(
    event: OrderPlacedEvent,
    store: InMemoryReceiptStore,
    sender: ReceiptSender,
    audit: ReceiptAuditLog,
) -> dict[str, object]:
    # Participant: use `production_dedupe_lookup_token(event)` (see idempotency.py).
    lookup_key = starter_dedupe_lookup_token(event)
    existing = store.get_by_order_id(lookup_key)
    if existing is not None:
        audit.record(AUDIT_ACTION_DUPLICATE_RETRY, event, existing.receipt_id)
        return _result(existing, "duplicate", False)

    receipt_id = sender.send_receipt(event)
    record = store.save_new(event, receipt_id)
    audit.record(AUDIT_ACTION_RECEIPT_SENT, event, receipt_id)
    return _result(record, "sent", True)


def summarize_receipt_workflow(
    store: InMemoryReceiptStore,
    sender: ReceiptSender,
    audit: ReceiptAuditLog,
) -> dict[str, object]:
    duplicate_retries = [event for event in audit.events if event["action"] == AUDIT_ACTION_DUPLICATE_RETRY]
    return {
        "stored_receipts": len(store.all_records()),
        "sent_receipts": len(sender.sent_receipts),
        "audit_events": len(audit.events),
        "duplicate_retries": len(duplicate_retries),
        "order_ids": [record.order_id for record in store.all_records()],
    }


class LambdaReceiptWorkflow:
    def __init__(
        self,
        store: InMemoryReceiptStore | None = None,
        sender: ReceiptSender | None = None,
        audit: ReceiptAuditLog | None = None,
    ) -> None:
        self.store = store or InMemoryReceiptStore()
        self.sender = sender or ReceiptSender()
        self.audit = audit or ReceiptAuditLog()

    def handle(self, event: OrderPlacedEvent) -> dict[str, object]:
        return handle_order_receipt_event(event, self.store, self.sender, self.audit)

    def summarize(self) -> dict[str, object]:
        return summarize_receipt_workflow(self.store, self.sender, self.audit)

