from __future__ import annotations

from dataclasses import dataclass


def _non_empty(label: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class OrderPlacedEvent:
    order_id: str
    customer_email: str
    amount_cents: int
    currency: str
    lambda_request_id: str
    retry_attempt: int = 0

    def __post_init__(self) -> None:
        _non_empty("order_id", self.order_id)
        if "@" not in self.customer_email:
            raise ValueError("customer_email must be valid")
        if self.amount_cents < 0:
            raise ValueError("amount_cents must be non-negative")
        _non_empty("currency", self.currency)
        _non_empty("lambda_request_id", self.lambda_request_id)
        if self.retry_attempt < 0:
            raise ValueError("retry_attempt must be non-negative")

    def business_key(self) -> str:
        return self.order_id.strip()

    def envelope_identity(self) -> tuple[str, str]:
        return (self.order_id.strip(), self.lambda_request_id.strip())


@dataclass(frozen=True)
class ReceiptRecord:
    order_id: str
    receipt_id: str
    customer_email: str
    amount_cents: int
    currency: str
    first_lambda_request_id: str

    def as_summary_tuple(self) -> tuple[str, str, str]:
        return (self.order_id, self.receipt_id, self.first_lambda_request_id)


def normalize_currency(currency: str) -> str:
    return currency.strip().upper()


def currency_is_iso_upper(code: str) -> bool:
    normalized = normalize_currency(code)
    return len(normalized) == 3 and normalized.isalpha()


def amount_non_zero(amount_cents: int) -> bool:
    return amount_cents > 0


def order_event_label(event: OrderPlacedEvent) -> str:
    return f"{event.order_id}@{event.lambda_request_id}"


def receipt_matches_order(record: ReceiptRecord, order_id: str) -> bool:
    return record.order_id == order_id


def describe_payment_minor_units(amount_cents: int) -> str:
    return f"{amount_cents} minor units"


def event_retry_generation(event: OrderPlacedEvent) -> str:
    return "initial" if event.retry_attempt == 0 else f"retry-{event.retry_attempt}"


def receipt_stable_fingerprint(record: ReceiptRecord) -> str:
    return "|".join((record.order_id, record.receipt_id, record.currency))

